// Dédoublonne (mémoire 30 jours, en exécution automatique seulement)
// et met les posts LinkedIn et les tweets X au même format pour Claude.
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const now = Date.now();
for (const [k, t] of Object.entries(staticData.seen)) {
  if (now - t > 30 * 864e5) delete staticData.seen[k];
}

function normaliser(p) {
  // Tweet X : champs text/fullText et author.userName
  const a = p.author || {};
  if (a.userName || p.fullText || p.twitterUrl || (p.url && /x\.com|twitter\.com/.test(p.url))) {
    return {
      source: 'X',
      key: 'x:' + (p.id || p.url),
      author: a.name || a.userName || 'Inconnu',
      headline: a.description || '',
      authorUrl: a.url || (a.userName ? 'https://x.com/' + a.userName : ''),
      postUrl: p.url || p.twitterUrl || '',
      postedAgo: p.createdAt || '',
      text: p.fullText || p.text || '',
    };
  }
  // Post LinkedIn (harvestapi)
  return {
    source: 'LinkedIn',
    key: p.id || p.linkedinUrl,
    author: a.name || 'Inconnu',
    headline: a.info || '',
    authorUrl: a.linkedinUrl || '',
    postUrl: p.linkedinUrl || (p.socialContent && p.socialContent.shareUrl) || '',
    postedAgo: (p.postedAt && p.postedAt.postedAgoText) || '',
    text: p.content || '',
  };
}

const out = [];
for (const item of $input.all()) {
  const n = normaliser(item.json || {});
  if (!n.key || staticData.seen[n.key]) continue;
  staticData.seen[n.key] = now;
  n.text = n.text.replace(/\s+/g, ' ').trim().slice(0, 3000);
  if (!n.text) continue;
  delete n.key;
  out.push({ json: n });
}
// Aucun nouveau post : on s'arrête là (pas d'appel à Claude, pas d'e-mail).
return out;

