// Associe chaque réponse de Claude à son post, filtre et construit le digest missions.
const SEUIL = 60;
const posts = $('Dédoublonner et préparer').all();
const reponses = $input.all();
const esc = s => String(s || '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const labels = { demande_explicite: 'Demande explicite', recommandation_demandee: 'Recommandation demandée', besoin_implicite: 'Besoin implicite', offre_emploi: 'Poste salarié', autre: 'Autre' };
const urg = { haute: '🔴 urgent', moyenne: '🟠', basse: '' };

const retenus = [];
let erreurs = 0;
reponses.forEach((r, i) => {
  const post = (posts[i] && posts[i].json) || {};
  const msg = r.json || {};
  if (msg.error || msg.stop_reason === 'refusal') { erreurs++; return; }
  const bloc = (msg.content || []).find(b => b.type === 'text');
  let q;
  try { q = JSON.parse(bloc.text); } catch (e) { erreurs++; return; }
  if (q.est_mission && q.score >= SEUIL) retenus.push({ ...post, ...q });
});
retenus.sort((a, b) => b.score - a.score);

const date = new Date().toLocaleDateString('fr-CA', { timeZone: 'America/Toronto', weekday: 'long', day: 'numeric', month: 'long' });
const carte = p => `
  <div style="border:1px solid #ddd;border-radius:8px;padding:12px;margin:10px 0;">
    <div style="font-size:13px;color:#666;">Score <b>${p.score}</b> · ${esc(labels[p.type_signal] || p.type_signal)} · ${esc(p.persona_auteur)}${urg[p.urgence] ? ' · ' + urg[p.urgence] : ''}${p.postedAgo ? ' · ' + esc(p.postedAgo) : ''}</div>
    <div style="font-weight:bold;margin:4px 0;">${esc(p.besoin || 'Besoin non précisé')}${p.entreprise ? ' · ' + esc(p.entreprise) : ''}${p.localisation ? ' · ' + esc(p.localisation) : ''}</div>
    <div style="font-size:13px;"><a href="${esc(p.authorUrl)}">${esc(p.author)}</a> · ${esc(p.headline)}</div>
    <p style="font-size:14px;margin:8px 0;"><b>Pourquoi :</b> ${esc(p.raison)}</p>
    <p style="font-size:14px;margin:8px 0;background:#f4fff4;padding:8px;border-radius:6px;"><b>Angle :</b> ${esc(p.angle_approche)}</p>
    <p style="font-size:13px;color:#444;">${esc(p.text.slice(0, 280))}…</p>
    <a href="${esc(p.postUrl)}">Voir le post</a>
  </div>`;

const resume = `${reponses.length} nouveaux posts analysés · ${retenus.length} opportunités retenues (score ≥ ${SEUIL})${erreurs ? ` · ${erreurs} en erreur` : ''}`;
const html = `<h2>Missions freelance, ${esc(date)}</h2><p>${resume}</p>` +
  (retenus.length ? retenus.map(carte).join('') : '<p>Aucune opportunité assez pertinente aujourd\'hui.</p>');

return [{ json: { count: retenus.length, subject: `Missions freelance : ${retenus.length} opportunités`, html } }];
